mapper.select:
select 
SUM(psp.amount) as amount
from PTL_SEC_POSITION psp
left join fin_product fp on fp.FINPROD_ID=psp.FINPROD_ID
where psp.cdate=TO_DATE(#{valDate},'YYYY-MM-DD')
and psp.branch=0
and psp.hoding_type=#{POSITION_TYPE_03}
and fp.FINPROD_MARKET_ID=#{ptlId}
and fp.FINPROD_TYPE2=#{FINPROD_TYPE_TG_F17}

select psp.portfolio_id as portfolioId,
	SUM(psp.amount) as amount
	from PTL_SEC_POSITION psp
	left join fin_product fp on fp.FINPROD_ID=psp.FINPROD_ID
	where psp.cdate=TO_DATE(#{valDate},'YYYY-MM-DD')
	and psp.branch=0
	and psp.hoding_type=#{POSITION_TYPE_03}
	and fp.FINPROD_MARKET_ID=#{ptlId}
    and fp.FINPROD_TYPE2=#{FINPROD_TYPE_TG_F17}
	group by psp.portfolio_id
